package com.acme.support.sla;

import java.time.Duration;
import java.time.Instant;

/**
 * Escalates tickets that have breached their SLA deadline without resolution.
 */
public class SlaBreachEscalator {

    private final TicketRepository tickets;
    private final SlaCalculator slaCalculator;

    public SlaBreachEscalator(TicketRepository tickets, SlaCalculator slaCalculator) {
        this.tickets = tickets;
        this.slaCalculator = slaCalculator;
    }

    public int escalateBreaches(Instant now) {
        int escalated = 0;
        for (Ticket t : tickets.findOpenTickets()) {
            Duration allowed = slaCalculator.allowedFor(t.getPriority(), t.getCustomerTier());
            Instant deadline = t.getOpenedAt().plus(allowed);
            if (now.isAfter(deadline) && t.getStatus() != TicketStatus.ESCALATED) {
                t.setStatus(TicketStatus.ESCALATED);
                t.setEscalatedAt(now);
                tickets.save(t);
                escalated++;
            }
        }
        return escalated;
    }
}

