package com.acme.support.sla;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;

/**
 * Calculates first-response deadlines from priority and service tier.
 */
public class FirstResponseDeadlineCalculator {

    private final Map<String, Map<String, Duration>> matrix;

    public FirstResponseDeadlineCalculator(Map<String, Map<String, Duration>> matrix) {
        this.matrix = matrix;
    }

    public Instant deadlineFor(String priority, String serviceTier, Instant openedAt) {
        Map<String, Duration> perPriority = matrix.get(serviceTier);
        if (perPriority == null) {
            throw new IllegalArgumentException("Unknown service tier: " + serviceTier);
        }
        Duration allowed = perPriority.get(priority);
        if (allowed == null) {
            throw new IllegalArgumentException("No response target for priority " + priority);
        }
        return openedAt.plus(allowed);
    }
}

