package com.acme.support.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Ticket submission endpoint: validate, create, route.
 */
@RestController
public class TicketSubmissionController {

    private final TicketRepository tickets;
    private final FirstResponseDeadlineCalculator deadlines;
    private final TicketRouter router;

    public TicketSubmissionController(TicketRepository tickets, FirstResponseDeadlineCalculator deadlines, TicketRouter router) {
        this.tickets = tickets;
        this.deadlines = deadlines;
        this.router = router;
    }

    @PostMapping("/tickets")
    public TicketView submit(@RequestBody TicketSubmissionRequest req) {
        if (req.getSubject() == null || req.getSubject().isBlank()) {
            throw new IllegalArgumentException("Subject is required");
        }
        if (req.getDescription() == null || req.getDescription().length() < 10) {
            throw new IllegalArgumentException("Description too short");
        }
        Ticket t = new Ticket(req.getCustomerId(), req.getSubject(), req.getDescription(), req.getPriority(), req.getCustomerTier());
        t.setFirstResponseDeadline(deadlines.deadlineFor(req.getPriority(), req.getCustomerTier(), java.time.Instant.now()));
        t.setQueue(router.selectQueue(t));
        return TicketView.from(tickets.save(t));
    }
}

