import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row on each ticket field change.
 */
public class TicketChangeAuditor {

    private final EntityManager em;

    public TicketChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String ticketId, String field, String oldValue, String newValue, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            TicketChangeEntry e = new TicketChangeEntry();
            e.setTicketId(ticketId);
            e.setField(field);
            e.setOldValue(oldValue);
            e.setNewValue(newValue);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

