import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises ticket priority changes.
 */
public class PriorityChangePolicy {

    private final TicketRepository tickets;
    private final StaffDirectory staff;

    public PriorityChangePolicy(TicketRepository tickets, StaffDirectory staff) {
        this.tickets = tickets;
        this.staff = staff;
    }

    public void assertMayChange(String userId, String ticketId) {
        Ticket t = tickets.require(ticketId);
        if (userId.equals(t.getAssigneeId())) {
            return;
        }
        if (staff.hasRole(userId, "TEAM_LEAD") || staff.hasRole(userId, "ADMIN")) {
            return;
        }
        throw new AccessDeniedException("User " + userId + " may not change priority of " + ticketId);
    }
}

