#include "support_db.h"

int write_queue_report(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "queue,open_tickets,median_frt_mins,sla_breaches\n");

    db_cursor_t *cur = NULL;
    if (db_open_queue_daily_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    queue_row_t row;
    while (db_queue_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%d,%.2f,%d\n",
                row.queue_name, row.open_count, row.median_frt_mins, row.sla_breaches);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

